  "  <button class='tab active' data-tab='all'>All</button>\n"
  "  <button class='tab' data-tab='enabled'>Enabled</button>\n"
  "  <button class='tab' data-tab='disabled'>Disabled</button>\n"
  "  <button class='tab' data-tab='unlisted'>Unlisted</button>\n"
  "  <button class='mobile-filter-btn' id='mobileFilter'>Filter</button>\n"
  "  <div class='spacer'></div>\n"
  "  <div class='status' id='status'><span>0</span> files</div>\n"
  "  <button class='shut' id='stopBtn' title='Stop server'>\n"
  "    <svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2'><path d='M18.36 6.64a9 9 0 1 1-12.72 0'/><line x1='12' y1='2' x2='12' y2='12'/></svg>\n"
  "    Stop\n"
  "  </button>\n"
  "</nav>\n"
  "<div class='filter-bar'>\n"
  "  <label>Section</label>\n"
  "  <select id='sectFilter'><option value=''>All sections</option></select>\n"
  "  <button class='sort-btn' id='sortBtn' title='Toggle sort'>A-Z</button>\n"
  "  <input type='text' id='search' placeholder='Search files...'>\n"
  "  <div class='view-toggle'>\n"
  "    <button class='sort-btn active' id='viewGrid' title='Grid view'>Grid</button>\n"
  "    <button class='sort-btn' id='viewList' title='List view'>List</button>\n"
  "  </div>\n"
  "  <button class='sort-btn' id='selectAllBtn' title='Select/unselect all filtered'>Select all</button>\n"
  "  <button class='sort-btn' id='uploadBtn' title='Upload file'>+ Upload</button>\n"
  "  <button class='sort-btn' id='addBtn' title='Add ini entry'>+ Entry</button>\n"
  "  <div class='count' id='count'>showing <span>0</span></div>\n"
  "</div>\n"
  "<div class='sel-bar' id='selBar'>\n"
  "  <div class='count-label'><span id='selCount'>0</span> selected</div>\n"
  "  <button class='sort-btn dl' id='selDownload' title='Download selected'>Download</button>\n"
  "  <button class='sort-btn del' id='selDelete' title='Delete selected'>Delete</button>\n"
  "  <button class='sort-btn clear' id='selClear' title='Clear selection'>Clear</button>\n"
  "</div>\n"
  "<div class='gallery' id='gallery'><div class='grid' id='grid'></div><div class='list' id='list'></div><div class='empty' id='empty' style='display:none'>\n"
  "  <div class='icon'>&#9673;</div>  <div class='msg'>No files found</div>\n"
  "  <div class='sub'>Upload a file or add an entry to plugins.ini</div>\n"
  "</div></div>\n"
  "<input type='file' id='fileInput' style='display:none'>\n"
  "<div class='modal-overlay' id='modal'><div class='modal' style='max-width:520px;width:90%'>\n"
  "  <div class='modal-header'><div class='title' id='modalTitle'></div>\n"
  "  <button class='close' id='modalClose'>&times;</button></div>\n"
  "  <div class='modal-body' style='display:block;padding:8px 0'><table class='detail-table' id='detailTable'></table></div>\n"
  "  <div class='modal-footer'><div class='info' id='modalInfo'></div>\n"
  "    <button class='btn danger' id='modalDelete'>Delete</button>\n"
  "    <button class='btn primary' id='modalToggle'>Toggle</button>\n"
  "  </div>\n"
  "</div></div>\n"
  "<div class='modal-overlay' id='confirmModal'><div class='modal confirm'>\n"
  "  <div class='modal-header'><div class='title'>Confirm</div></div>\n"
  "  <div id='confirmBody'></div>\n"
  "  <div class='modal-footer'><div class='info'></div>\n"
  "    <button class='btn' id='confirmCancel'>Cancel</button>\n"
  "    <button class='btn danger' id='confirmOk'>OK</button>\n"
  "  </div>\n"
  "</div></div>\n"
  "<div class='modal-overlay' id='addModal'><div class='modal' style='max-width:420px;width:90%'>\n"
  "  <div class='modal-header'><div class='title'>Add plugin entry</div>\n"
  "  <button class='close' id='addClose'>&times;</button></div>\n"
  "  <div class='modal-body' style='display:block;padding:14px 16px'>\n"
  "    <div style='margin-bottom:10px'><div class='add-label'>Section</div><select id='addSection' class='add-field'></select></div>\n"
  "    <div id='addNewWrap' style='display:none;margin-bottom:10px'><div class='add-label'>New section</div><input type='text' id='addNewSection' class='add-field' placeholder='CUSA00001'></div>\n"
  "    <div style='margin-bottom:10px'><div class='add-label'>Pick from files on disk</div><select id='addPick' class='add-field'><option value=''>-- or type filename below --</option></select></div>\n"
  "    <div style='margin-bottom:10px'><div class='add-label'>Filename + extension</div><input type='text' id='addFilename' class='add-field' placeholder='my_plugin.prx'></div>\n"
  "    <div style='font-size:11px;color:var(--dm);word-break:break-all' id='addPreview'>/data/GoldHEN/plugins/...</div>\n"
  "  </div>\n"
  "  <div class='modal-footer'><div class='info'>path is filled in automatically</div>\n"
  "    <button class='btn' id='addCancel'>Cancel</button>\n"
  "    <button class='btn primary' id='addOk'>Add</button>\n"
  "  </div>\n"
  "</div></div>\n"
  "<div id='toast'></div>\n"
  "<script>\n"
  "var S={sections:[],files:[],tab:'all',sect:'',q:'',asc:true,sel:null,view:'grid',selected:{}};\n"
  "var $=function(id){return document.getElementById(id);};\n"
  "function toast(m,e){var t=$('toast');t.textContent=m;t.className=e?'show err':'show';setTimeout(function(){t.className='';},2200);}\n"
  "function fmtSize(b){if(b<1024)return b+' B';if(b<1048576)return (b/1024).toFixed(1)+' KB';return (b/1048576).toFixed(2)+' MB';}\n"
  "function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\n"
  "function allEntries(){var r=[];S.sections.forEach(function(s){s.entries.forEach(function(e){r.push({section:s.id,path:e.path,file:e.file,enabled:e.enabled});});});return r;}\n"
  "function fileInfo(n){for(var i=0;i<S.files.length;i++)if(S.files[i].name===n)return S.files[i];return null;}\n"
  "function selectedNames(){var out=[];for(var k in S.selected)if(S.selected[k])out.push(k);return out;}\n"
  "function syncSelUI(){\n"
  "  var n=selectedNames().length;\n"
  "  $('selBar').classList.toggle('show',n>0);\n"
  "  $('selCount').textContent=n;\n"
  "  var rows=document.querySelectorAll('.card,.list-row');\n"
  "  for(var i=0;i<rows.length;i++){var nm=rows[i].getAttribute('data-name');if(nm)rows[i].classList.toggle('selected',!!S.selected[nm]);}\n"
  "  var boxes=document.querySelectorAll('.sel-box,.row-check');\n"
  "  for(var j=0;j<boxes.length;j++){var fn=boxes[j].getAttribute('data-file');if(fn)boxes[j].checked=!!S.selected[fn];}\n"
  "}\n"
  "function setSel(name,on){if(on)S.selected[name]=true;else delete S.selected[name];syncSelUI();}\n"
  "function clearSel(){S.selected={};syncSelUI();}\n"
  "async function load(){try{var r=await fetch('/api/plugins');var j=await r.json();S.sections=j.sections||[];S.files=j.files||[];buildSect();buildAddPick();render();}catch(e){toast('Failed to load plugins',1);}}\n"
  "function buildSect(){var s=$('sectFilter');var cur=s.value;s.innerHTML='<option value=\"\">All sections</option>';S.sections.forEach(function(x){var o=document.createElement('option');o.value=x.id;o.textContent=x.id+' ('+x.entries.length+')';s.appendChild(o);});s.value=cur;}\n"
  "function buildAddPick(){var p=$('addPick');var cur=p.value;p.innerHTML='<option value=\"\">-- or type filename below --</option>';S.files.forEach(function(f){var o=document.createElement('option');o.value=f.name;o.textContent=f.name;p.appendChild(o);});p.value=cur;}\n"
  "function filtered(){var es=allEntries();var out=[];\n"
  "  if(S.tab==='unlisted'){S.files.forEach(function(f){out.push({section:'',path:'/data/GoldHEN/plugins/'+f.name,file:f.name,enabled:false,unlisted:true});});}\n"
  "  else{es.forEach(function(e){if(S.tab==='enabled'&&!e.enabled)return;if(S.tab==='disabled'&&e.enabled)return;out.push(e);});}\n"
  "  if(S.sect)out=out.filter(function(e){return e.section===S.sect;});\n"
  "  if(S.q)out=out.filter(function(e){return e.file.toLowerCase().indexOf(S.q)>=0||e.path.toLowerCase().indexOf(S.q)>=0;});\n"
  "  out.sort(function(a,b){return S.asc?a.file.localeCompare(b.file):b.file.localeCompare(a.file);});\n"
  "  return out;}\n"
  "function badge(e){if(e.unlisted)return \"<span class='type-badge photo'>unlisted</span>\";return e.enabled?\"<span class='type-badge on'>on</span>\":\"<span class='type-badge off'>off</span>\";}\n"
  "var PUZZLE=\"<svg viewBox='0 0 24 24'><path d='M14 7V5a2 2 0 0 0-4 0v2H7a2 2 0 0 0-2 2v3h2a2 2 0 1 1 0 4H5v3a2 2 0 0 0 2 2h3v-2a2 2 0 1 1 4 0v2h3a2 2 0 0 0 2-2v-3h-2a2 2 0 1 1 0-4h2V9a2 2 0 0 0-2-2h-3z'/></svg>\";\n"
  "var TRASH=\"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M3 6h18M8 6V4h8v2m1 0v14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2V6'/><line x1='10' y1='11' x2='10' y2='17'/><line x1='14' y1='11' x2='14' y2='17'/></svg>\";\n"
  "function render(){var list=filtered();var g=$('grid'),l=$('list');\n"
  "  g.innerHTML='';l.innerHTML='';\n"
  "  $('empty').style.display=list.length?'none':'flex';\n"
  "  $('count').innerHTML='showing <span>'+list.length+'</span>';\n"
  "  var n=allEntries().length;$('status').innerHTML='<span>'+n+'</span> plugins';\n"
  "  $('gallery').classList.toggle('list-mode',S.view==='list');\n"
  "  var host=S.view==='list'?l:g;\n"
  "  list.forEach(function(e){renderItem(host,e);});\n"
  "  syncSelUI();}\n"
  "function renderItem(el,e){var f=fileInfo(e.file);var sz=f?fmtSize(f.size):'missing';\n"
  "  var d=document.createElement('div');\n"
  "  if(S.view==='list'){\n"
  "    d.className='list-row'+(e.enabled?' enabled':'');\n"
  "    d.setAttribute('data-name',e.file);\n"
  "    d.innerHTML=\"<input type='checkbox' class='row-check' data-file='\"+esc(e.file)+\"'><div class='row-icon'>\"+PUZZLE+\"</div><div class='row-name'><div class='row-title'>\"+esc(e.file)+\"</div><div class='row-sub'>\"+esc(e.section||'disk')+\" \"+badge(e)+\"</div></div><div class='row-meta'>\"+sz+\"</div><div class='row-actions'><button class='card-btn dl'>\"+(e.unlisted?'Add':(e.enabled?'Disable':'Enable'))+\"</button><button class='card-btn'>Details</button><button class='card-btn del'>\"+TRASH+\"</button></div>\";\n"
  "  } else {\n"
  "    d.className='card'+(e.enabled?' enabled':'');\n"
  "    d.setAttribute('data-name',e.file);\n"
  "    d.innerHTML=\"<input type='checkbox' class='sel-box' data-file='\"+esc(e.file)+\"'><div class='card-thumb'>\"+PUZZLE+\"</div><div class='card-info'><div class='card-title'>\"+esc(e.file)+\"</div><div class='card-meta'><span>\"+esc(e.section||'disk')+\"</span><span>\"+sz+\"</span></div><div style='margin-top:4px'>\"+badge(e)+\"</div><div class='card-actions'><button class='card-btn dl'>\"+(e.unlisted?'Add':(e.enabled?'Disable':'Enable'))+\"</button><button class='card-btn'>Details</button><button class='card-btn del'>\"+TRASH+\"</button></div></div>\";\n"
  "  }\n"
  "  var btns=d.querySelectorAll('.card-btn');\n"
  "  btns[0].onclick=function(ev){ev.stopPropagation();if(e.unlisted)openAddModal('default',e.file);else toggle(e);};\n"
  "  btns[1].onclick=function(ev){ev.stopPropagation();openModal(e);};\n"
  "  btns[2].onclick=function(ev){ev.stopPropagation();askDelete(e);};\n"
  "  var box=d.querySelector('.sel-box,.row-check');\n"
  "  box.onclick=function(ev){ev.stopPropagation();setSel(e.file,box.checked);};\n"
  "  d.onclick=function(){openModal(e);};\n"
  "  el.appendChild(d);}\n"
  "function toggleSelectAll(){\n"
  "  var list=filtered();\n"
  "  if(!list.length)return;\n"
  "  var allOn=list.every(function(e){return S.selected[e.file];});\n"
  "  list.forEach(function(e){if(allOn)delete S.selected[e.file];else S.selected[e.file]=true;});\n"
  "  render();}\n"
  "function downloadSelected(){\n"
  "  var names=selectedNames();\n"
  "  if(!names.length){toast('Nothing selected',1);return;}\n"
  "  if(names.length===1){\n"
  "    var a=document.createElement('a');\n"
  "    a.href='/api/download?name='+encodeURIComponent(names[0]);\n"
  "    a.download=names[0];\n"
  "    document.body.appendChild(a);a.click();a.remove();\n"
  "    return;\n"
  "  }\n"
  "  toast('Packing '+names.length+' files into zip...');\n"
  "  fetch('/api/download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:names.join(',')})})\n"
  "    .then(function(r){if(!r.ok)throw new Error('failed');return r.blob();})\n"
  "    .then(function(blob){\n"
  "      var url=URL.createObjectURL(blob);\n"
  "      var a=document.createElement('a');\n"
  "      a.href=url;a.download='plugins-mgr.zip';\n"
  "      document.body.appendChild(a);a.click();a.remove();\n"
  "      setTimeout(function(){URL.revokeObjectURL(url);},2000);\n"
  "      toast('Downloading plugins-mgr.zip');\n"
  "    })\n"
  "    .catch(function(){toast('Zip download failed',1);});\n"
  "}\n"
  "function askDeleteSelected(){\n"
  "  var names=selectedNames();\n"
  "  if(!names.length){toast('Nothing selected',1);return;}\n"
  "  var shown=names.slice(0,3).join(', ');\n"
  "  var msg='Delete '+names.length+' file'+(names.length>1?'s':'')+'? '+shown+(names.length>3?' +'+(names.length-3)+' more':'')+' — files and ini refs are removed.';\n"
  "  confirmBox(msg,async function(){\n"
  "    var j=await post('/api/files',{names:names.join(','),clean_ini:'true'});\n"
  "    if(j.ok){toast('Deleted '+j.deleted+' file'+(j.deleted===1?'':'s'));clearSel();closeModal();load();}\n"
  "    else toast(j.error||'Delete failed',1);});}\n"
  "async function post(url,body){var r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return r.json();}\n"
  "async function toggle(e){var j=await post('/api/toggle',{section:e.section,path:e.path});if(j.ok){toast('Toggled '+e.file);load();}else toast(j.error||'Toggle failed',1);}\n"
  "function openAddModal(section,file){\n"
  "  var sel=$('addSection'), newWrap=$('addNewWrap');\n"
  "  sel.innerHTML='<option value=\"\">-- select a section --</option>';\n"
  "  S.sections.forEach(function(x){var o=document.createElement('option');o.value=x.id;o.textContent=x.id;sel.appendChild(o);});\n"
  "  if(section && S.sections.some(function(x){return x.id===section;})) sel.value=section;\n"
  "  if(file) $('addFilename').value=file;\n"
  "  newWrap.style.display='none';\n"
  "  updateAddPreview();\n"
  "  $('addModal').classList.add('active');\n"
  "}\n"
  "function updateAddPreview(){\n"
  "  var filename=$('addFilename').value.trim();\n"
  "  var section=$('addSection').value || $('addNewSection').value.trim();\n"
  "  $('addPreview').textContent=section && filename ? '/data/GoldHEN/plugins/'+filename : '/data/GoldHEN/plugins/...';\n"
  "}\n"
  "async function addEntryFromModal(){\n"
  "  var filename=$('addFilename').value.trim();\n"
  "  var section=$('addSection').value || $('addNewSection').value.trim();\n"
  "  if(!filename){toast('Enter a filename + extension',1);return;}\n"
  "  if(filename.indexOf('/')>=0 || filename.indexOf('\\\\')>=0 || filename.indexOf('..')>=0){toast('Invalid filename',1);return;}\n"
  "  if(!section){toast('Select or create a section',1);return;}\n"
  "  var j=await post('/api/entry',{section:section,path:'/data/GoldHEN/plugins/'+filename,op:'add'});\n"
  "  if(j.ok){toast(j.exists?'Already exists':'Entry added');closeAddModal();load();}\n"
  "  else toast(j.error||'Add failed',1);\n"
  "}\n"
  "function closeAddModal(){$('addModal').classList.remove('active');}\n"
  "function askDelete(e){confirmBox('Delete '+e.file+'? File + ini refs are removed.',async function(){\n"
  "  var j=await post('/api/file',{name:e.file,op:'delete',clean_ini:true});\n"
  "  if(j.ok){toast('Deleted '+e.file);closeModal();load();}else toast(j.error||'Delete failed',1);});}\n"
  "var confirmCb=null;\n"
  "function confirmBox(msg,cb){$('confirmBody').textContent=msg;confirmCb=cb;$('confirmModal').classList.add('active');$('modal').classList.add('behind-confirm');}\n"
  "$('confirmOk').onclick=function(){$('confirmModal').classList.remove('active');$('modal').classList.remove('behind-confirm');if(confirmCb)confirmCb();};\n"
  "$('confirmCancel').onclick=function(){$('confirmModal').classList.remove('active');$('modal').classList.remove('behind-confirm');};\n"
  "function openModal(e){S.sel=e;var f=fileInfo(e.file);\n"
  "  $('modalTitle').textContent=e.file;\n"
  "  $('detailTable').innerHTML='<tr><td>Path</td><td>'+esc(e.path)+'</td></tr><tr><td>Section</td><td>'+esc(e.section||'(file only)')+'</td></tr><tr><td>State</td><td>'+(e.unlisted?'unlisted (not in ini)':(e.enabled?'enabled':'disabled'))+'</td></tr><tr><td>Size</td><td>'+(f?fmtSize(f.size):'not on disk')+'</td></tr>';\n"
  "  $('modalInfo').textContent=e.section?e.section+' :: '+e.file:'on disk only';\n"
  "  $('modalToggle').textContent=e.enabled?'Disable':'Enable';\n"
  "  $('modal').classList.add('active');}\n"
  "function closeModal(){$('modal').classList.remove('active');}\n"
  "$('modalClose').onclick=closeModal;\n"
  "$('modal').onclick=function(e){if(e.target===$('modal'))closeModal();};\n"
  "$('modalToggle').onclick=function(){if(!S.sel)return;var e=S.sel;closeModal();if(e.unlisted)openAddModal(e.section||'default',e.file);else toggle(e);};\n"
  "$('modalDelete').onclick=function(){if(!S.sel)return;var e=S.sel;askDelete(e);};\n"
  "document.querySelectorAll('.tab').forEach(function(t){t.onclick=function(){document.querySelectorAll('.tab').forEach(function(x){x.classList.remove('active');});t.classList.add('active');S.tab=t.getAttribute('data-tab');render();};});\n"
  "$('mobileFilter').onclick=function(){var tabs=['all','enabled','disabled','unlisted'];var i=(tabs.indexOf(S.tab)+1)%tabs.length;S.tab=tabs[i];document.querySelectorAll('.tab').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-tab')===S.tab);});toast('Filter: '+S.tab);render();};\n"
  "$('sectFilter').onchange=function(e){S.sect=e.target.value;render();};\n"
  "$('search').oninput=function(e){S.q=e.target.value.toLowerCase();render();};\n"
  "$('sortBtn').onclick=function(){S.asc=!S.asc;$('sortBtn').textContent=S.asc?'A-Z':'Z-A';render();};\n"
  "$('addBtn').onclick=function(){openAddModal('default','');};\n"
  "$('addClose').onclick=closeAddModal;\n"
  "$('addCancel').onclick=closeAddModal;\n"
  "$('addOk').onclick=addEntryFromModal;\n"
  "$('addSection').onchange=function(){$('addNewWrap').style.display=$('addSection').value?'none':'block';updateAddPreview();};\n"
  "$('addNewSection').oninput=updateAddPreview;\n"
  "$('addFilename').oninput=updateAddPreview;\n"
  "$('addPick').onchange=function(){if(this.value)$('addFilename').value=this.value;updateAddPreview();};\n"
  "$('sectFilter').onchange=function(e){S.sect=e.target.value;render();};\n"
  "$('search').oninput=function(e){S.q=e.target.value.toLowerCase();render();};\n"
  "$('sortBtn').onclick=function(){S.asc=!S.asc;$('sortBtn').textContent=S.asc?'A-Z':'Z-A';render();};\n"
  "$('addBtn').onclick=function(){openAddModal('default','');};\n"
  "$('uploadBtn').onclick=function(){$('fileInput').click();};\n"
  "$('viewGrid').onclick=function(){S.view='grid';$('viewGrid').classList.add('active');$('viewList').classList.remove('active');render();};\n"
  "$('viewList').onclick=function(){S.view='list';$('viewList').classList.add('active');$('viewGrid').classList.remove('active');render();};\n"
  "$('selectAllBtn').onclick=toggleSelectAll;\n"
  "$('selDownload').onclick=downloadSelected;\n"
  "$('selDelete').onclick=askDeleteSelected;\n"
  "$('selClear').onclick=clearSel;\n"
  "$('fileInput').onchange=async function(){var f=$('fileInput').files[0];if(!f)return;\n"
  "  toast('Uploading '+f.name+'...');\n"
  "  try{var r=await fetch('/api/upload?filename='+encodeURIComponent(f.name),{method:'POST',body:f});var j=await r.json();if(j.ok){toast('Uploaded '+f.name);load();}else toast(j.error||'Upload failed',1);}catch(e){toast('Upload failed',1);}\n"
  "  $('fileInput').value='';};\n"
  "$('stopBtn').onclick=function(){confirmBox('Stop the Plugins Mgr server?',async function(){try{await fetch('/api/stop',{method:'POST'});toast('Server stopped');}catch(e){toast('Server stopped');}});};\n"
  "load();\n"
  "</script>\n"
  "</body>\n"
  ;
